const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");

// Cross-host NotebookEntry conformance. Fixtures live in the plugin repo
// because the schema doc is canonical here; golden files are generated by
// the desktop Rust implementation via its ignored generator test.

const FIXTURE_DIR = path.join(__dirname, "fixtures", "cross-host");

function readJson(name) {
  return JSON.parse(fs.readFileSync(path.join(FIXTURE_DIR, name), "utf8"));
}

function readText(name) {
  // Windows checkouts may CRLF-normalize text fixtures; generated TSV uses LF.
  return fs.readFileSync(path.join(FIXTURE_DIR, name), "utf8").replace(/\r\n/g, "\n");
}

function freshNotebook() {
  const previous = globalThis.LyricLens;
  globalThis.LyricLens = {};
  delete require.cache[require.resolve("../src/notebook")];
  const Notebook = require("../src/notebook");
  return {
    Notebook,
    restore: () => {
      globalThis.LyricLens = previous;
      delete require.cache[require.resolve("../src/notebook")];
    }
  };
}

function makeFakePersistence(seed = []) {
  const rows = new Map(seed.map((e) => [e.id, e]));
  return {
    rows,
    async loadAll() {
      return Array.from(rows.values());
    },
    async put(entry) {
      rows.set(entry.id, entry);
    },
    async remove(id) {
      rows.delete(id);
    }
  };
}

function serializedEntries(entries, Notebook) {
  return entries.map((entry) => Notebook.serializeEntry(entry));
}

test("cross-host makeSongKey cases match the schema fixture", () => {
  const cases = readJson("cases.json");
  const { Notebook, restore } = freshNotebook();
  try {
    for (const c of cases.makeSongKey) {
      assert.equal(
        Notebook.makeSongKey(c.title, c.artist, c.durationMs),
        c.expected,
        c.name
      );
    }
  } finally {
    restore();
  }
});

test("cross-host export entries and Anki TSV match desktop golden", () => {
  const cases = readJson("cases.json");
  const desktopEnvelope = readJson("desktop-export.golden.json");
  const desktopAnki = readText("desktop-anki.golden.tsv");
  const { Notebook, restore } = freshNotebook();
  try {
    const pluginEnvelope = Notebook.buildExportEnvelope(
      cases.exportEntries,
      cases.exportTsMs
    );

    assert.equal(pluginEnvelope.schema, desktopEnvelope.schema);
    assert.equal(pluginEnvelope.exportedAt, desktopEnvelope.exportedAt);
    assert.equal(desktopEnvelope.exportedFrom, "desktop");
    assert.equal(pluginEnvelope.exportedFrom, "plugin");
    assert.equal(
      JSON.stringify(pluginEnvelope.entries),
      JSON.stringify(desktopEnvelope.entries)
    );
    assert.equal(Notebook.buildAnkiTsv(cases.exportEntries), desktopAnki);
  } finally {
    restore();
  }
});

test("cross-host merge cases match desktop golden", () => {
  const cases = readJson("cases.json");
  const expected = readJson("merge.golden.json");
  const { Notebook, restore } = freshNotebook();
  try {
    const actual = cases.mergeCases.map((c) => {
      const result = Notebook.mergeEntries(c.local, c.incoming, c.importTsMs);
      return {
        name: c.name,
        outcome: result.outcome,
        entry: Notebook.serializeEntry(result.entry)
      };
    });
    assert.equal(JSON.stringify(actual), JSON.stringify(expected));
  } finally {
    restore();
  }
});

test("cross-host invalid entries reject on the plugin validator", () => {
  const cases = readJson("cases.json");
  const { Notebook, restore } = freshNotebook();
  try {
    for (const c of cases.invalidEntries) {
      const err = Notebook.validateEntry(Notebook.withDefaults(c.entry));
      assert.notEqual(err, null, c.name);
    }
  } finally {
    restore();
  }
});

test("cross-host import end-to-end summary and entries match desktop golden", async () => {
  const cases = readJson("cases.json");
  const expected = readJson("import.golden.json");
  const { Notebook, restore } = freshNotebook();
  try {
    Notebook._setPersistenceForTest(makeFakePersistence(cases.importCase.seed));
    await Notebook.bootstrap();
    const summary = Notebook.importEntries(cases.importCase.envelope, {
      nowMs: cases.importCase.importTsMs
    });

    assert.deepEqual(
      {
        totalParsed: summary.totalParsed,
        imported: summary.imported,
        merged: summary.merged,
        skipped: summary.skipped,
        errorCount: summary.errors.length
      },
      {
        totalParsed: expected.summary.totalParsed,
        imported: expected.summary.imported,
        merged: expected.summary.merged,
        skipped: expected.summary.skipped,
        errorCount: expected.summary.errors.length
      }
    );
    assert.equal(
      JSON.stringify(serializedEntries(Notebook.listEntries(), Notebook)),
      JSON.stringify(expected.entries)
    );
  } finally {
    restore();
  }
});
